function LocaleButtons(): JSX.Element {
  const [, setLocale] = useLocale()

  return (
    <div className="flex space-x-4">
      <Button onClick={() => setLocale('en')}>English</Button>
      <Button onClick={() => setLocale('fr')}>French</Button>
      <Button onClick={() => setLocale('es')}>Spanish</Button>
    </div>
  )
}

function Template({
  maxDate,
  minDate,
  value,
  ...args
}: BetterDatePickerProps): JSX.Element {
  // Local state only displays the most recent onChange value; the picker
  // itself runs uncontrolled, seeded from the `value` control via
  // defaultValue. Clear (and changing the control) remounts it through the
  // key so the uncontrolled internal value resets too
  const [selected, setSelected] = useState<Date | [Date, Date] | null>(null)
  const [instance, setInstance] = useState(0)

  // Storybook's date control emits a Unix timestamp rather than a Date. The
  // component normalizes inverted min/max bounds itself, so they are passed
  // through as-is
  const min = minDate ? new Date(minDate) : undefined
  const max = maxDate ? new Date(maxDate) : undefined
  const defaultValue = value ? new Date(value as Date) : undefined

  const formatValue = (): string => {
    if (!selected) {
      return '—'
    }

    if (Array.isArray(selected)) {
      return `${selected[0].toLocaleDateString()} — ${selected[1].toLocaleDateString()}`
    }

    return selected.toLocaleDateString()
  }

  return (
    <div className="max-w-sm m-6 space-y-4">
      {/* The template drives every mode from Storybook controls, so the
          union props are pinned to the day branch to satisfy the compiler,
          mirroring the mode cast in CalendarTemplate */}
      <BetterDatePicker
        key={`${value}-${instance}`}
        {...(args as BetterDatePickerDayProps)}
        defaultValue={defaultValue as Date}
        maxDate={max}
        minDate={min}
        onChange={setSelected as (date: Date | null) => void}
      />
      <Typography variant="body2">Selected: {formatValue()}</Typography>
      <Button
        onClick={() => {
          setSelected(null)
          setInstance((count) => count + 1)
        }}
      >
        Clear
      </Button>
      <LocaleButtons />
    </div>
  )
}

function CalendarTemplate(args: BetterDatePickerProps): JSX.Element {
  const [value, setValue] = useState<Date | [Date, Date] | null>(null)

  return (
    <div className="m-6 space-y-4">
      <Calendar
        condensed={args.condensed}
        mode={args.mode as 'day'}
        onChange={setValue as (value: Date) => void}
        timezone={args.timezone}
        value={value as Date | null}
      />
      <Button onClick={() => setValue(null)}>Clear</Button>
      <LocaleButtons />
    </div>
  )
}

